package bookstore

import "sort"

// discounts[i] is the total cost, in cents, of a group of i distinct books.
// A single book costs 800 cents ($8.00); groups of 2, 3, 4 and 5 distinct
// books get 5%, 10%, 20% and 25% discounts respectively.
var discounts = [6]int{0, 800, 1520, 2160, 2560, 3000}

// Cost returns the total price, in cents, of the given basket of books,
// applying the largest possible discount.
//
// books is a list of book identifiers, where each value is in the range
// 1..5 (the five titles of the series).
func Cost(books []int) int {
	var counts [5]int
	for _, b := range books {
		if b >= 1 && b <= 5 {
			counts[b-1]++
		}
	}
	return cost(counts[:])
}

// cost computes the cheapest way to group the books, given the (unsorted)
// number of copies of each of the five titles.
//
// The strategy is to form groups round by round, taking one copy of each of
// the titles that still have the most remaining copies. Groups of five are
// the best value per book, but two groups of four (2560 + 2560) beat one
// group of five plus one group of three (3000 + 2160). So whenever all five
// titles are present and the third-most common title has strictly more copies
// than the fourth, we form a group of four instead of five; this keeps the
// rarer titles available to pair up into further groups of four.
func cost(counts []int) int {
	total := 0
	for counts[0] > 0 {
		sort.Slice(counts, func(i, j int) bool { return counts[i] > counts[j] })

		// Number of titles that still have at least one copy.
		size := 0
		for i := 0; i < 5; i++ {
			if counts[i] == 0 {
				break
			}
			size++
		}

		// Prefer a group of four over a group of five when doing so leads to
		// a cheaper overall grouping (see the comment above).
		if size == 5 && counts[2] > counts[3] {
			size = 4
		}

		for i := 0; i < size; i++ {
			counts[i]--
		}
		total += discounts[size]
	}
	return total
}

